# Write your MySQL query statement below
select x.student_id , x.student_name , x.subject_name , count(y.subject_name) as attended_exams from (select s.student_id , s.student_name , sub.subject_name from students as s cross join subjects as sub ) as x left join (select * from examinations) as y on x.student_id=y.student_id and x.subject_name=y.subject_name group by x.student_id , x.student_name , x.subject_name order by student_id , subject_name asc